tool.command:
set -euo pipefail;

curl -L "${vcf_url}" -o input_file;

if file input_file | grep -q BCF; then
    mv input_file input.bcf;
    bcftools index -c input.bcf;
    bcftools index --stats input.bcf > index_stats.txt;
else
    mv input_file input.vcf.gz;
    bcftools index -c input.vcf.gz;
    bcftools index --stats input.vcf.gz > index_stats.txt;
fi
